package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.time.temporal.ChronoUnit;
import net.officefloor.hq.app.rate.Rates;
import net.officefloor.hq.app.settings.Settings;
import net.officefloor.hq.app.sheet.Sheets;
import org.springframework.stereotype.Service;

/** The figure a claim shows and totals: the due fixed when it was settled, else the greater of the
 *  sheet's floor in force on the claim's date and its figure plus its late charge, where its figure is
 *  the one its person's last statement bound it to, else live at its person's grade's rate in force on
 *  the claim's date (null, n/a, when there is no rate). A correction has neither floor nor charge. Every rounding of a claim's live figures follows
 *  the sheet's policy date: half up for a claim dated before it, half to even on or after it. */
@Service
public class Figures {

    private final Rates rates;
    private final Settings settings;
    private final Sheets sheets;
    private final Claims claims;

    public Figures(Rates rates, Settings settings, Sheets sheets, Claims claims) {
        this.rates = rates;
        this.settings = settings;
        this.sheets = sheets;
        this.claims = claims;
    }

    /** The sheet's policy date: as set, else the sheet's today. */
    public LocalDate policyDate(String sheetId) {
        LocalDate set = settings.policyDate(sheetId);
        return set != null ? set : sheets.today(sheetId);
    }

    /** How the claim's live figures round: half up when the claim is dated before the sheet's policy
     *  date, half to even on or after it. A correction rounds by the date of the claim it corrects. */
    public RoundingMode rounding(Claim claim) {
        return roundingDate(claim).isBefore(policyDate(claim.getSheetId())) ? RoundingMode.HALF_UP : RoundingMode.HALF_EVEN;
    }

    /** The date the claim rounds by: its own, or for a correction that of the claim it corrects. */
    public LocalDate roundingDate(Claim claim) {
        if (claim.getCorrects() == null) return claim.getDate();
        LocalDate corrected = claims.dateOf(claim.getSheetId(), claim.getPersonId(), claim.getCorrects());
        return corrected != null ? corrected : claim.getDate();
    }

    /** The claim's due as the screen shows and totals it: its figure plus its late charge while it
     *  is overdue, raised to the sheet's floor in force on the claim's date when it is below it (a
     *  correction has neither). A settled claim's fixed due already holds the charge and floor it had then. */
    public BigDecimal due(Claim claim, String grade) {
        BigDecimal figure = figure(claim, grade);
        if (figure == null || claim.getDue() != null || claim.isCorrection()) return figure;
        return figure.add(charge(claim, grade, figure)).max(settings.floor(claim.getSheetId(), claim.getDate()));
    }

    /** The claim's figure without any late charge or floor: the fixed due, else the bound figure, else live.
     *  A PENDING claim is not bound by a statement: it keeps its binding but shows its live figure. */
    public BigDecimal figure(Claim claim, String grade) {
        if (claim.getDue() != null) return claim.getDue();
        if (claim.isStated() && claim.getStatus() != ClaimStatus.PENDING) return claim.getStatedDue();
        return live(claim, grade);
    }

    /** The date the claim goes overdue after: its due-by (fixed when it was added) plus the grace days
     *  of its person's grade in force on the claim's date (`grade`), in force on that date. */
    public LocalDate overdueFrom(Claim claim, String grade) {
        return claim.getDueBy().plusDays(settings.grace(claim.getSheetId(), grade, claim.getDate()));
    }

    /** Whether the claim is overdue: OPEN (or PENDING), not deferred, and its due-by plus its grace
     *  (see {@link #overdueFrom}) is before the sheet's today. */
    public boolean overdue(Claim claim, String grade) {
        if (!claim.getStatus().isOpen() || claim.isDeferred()) return false;
        LocalDate today = sheets.today(claim.getSheetId());
        return today != null && overdueFrom(claim, grade).isBefore(today);
    }

    /** The late charge on a figure of the claim: nothing unless the claim is OPEN (or PENDING), not deferred, and its due-by (fixed
     *  when it was added) plus its grace is before the sheet's today (a correction has none); then, for every full 30 days it is
     *  overdue, counted from its due-by plus its grace, the sheet's late percent in force on that boundary date (the due-by plus
     *  the grace plus 30, 60, 90 ... days) of the figure plus the charges of the boundaries before it (compounding), each rounded by the claim's rounding to two decimals, added up. A
     *  boundary whose percent is 0.00 adds nothing. Never bound by a statement: it follows the sheet's today. */
    public BigDecimal charge(Claim claim, String grade, BigDecimal figure) {
        BigDecimal none = BigDecimal.ZERO.setScale(2);
        if (figure == null || !claim.getStatus().isOpen() || claim.isDeferred() || claim.isCorrection()) return none;
        String sheetId = claim.getSheetId();
        LocalDate from = overdueFrom(claim, grade);
        long periods = ChronoUnit.DAYS.between(from, sheets.today(sheetId)) / 30;
        BigDecimal total = none;
        for (long k = 1; k <= periods; k++) {
            BigDecimal pct = settings.latePct(sheetId, from.plusDays(30 * k));
            if (pct.signum() == 0) continue;
            total = total.add(figure.add(total).multiply(pct).divide(BigDecimal.valueOf(100)).setScale(2, rounding(claim)));
        }
        return total;
    }

    /** The claim's due at its person's grade's rate in force on the claim's date: amount times the
     *  rate divided by 100, rounded by the claim's rounding to two decimals, before any late charge or
     *  floor (see {@link #due}); null when there is no rate. */
    public BigDecimal live(Claim claim, String grade) {
        BigDecimal pct = rates.pct(claim.getSheetId(), grade, claim.getDate());
        if (pct == null) return null;
        return claim.getAmount().multiply(pct).divide(BigDecimal.valueOf(100)).setScale(2, rounding(claim));
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.time.LocalDate;

/** A claim a person on a sheet has made, DRAFT (and unnumbered) until it is opened. `id` is null until the claim is first saved. */
public class Claim {
    private Long id;
    private final String sheetId;
    private long personId;
    private BigDecimal amount;
    private LocalDate date;
    private String note;
    private ClaimStatus status;
    private String number;
    private BigDecimal due;
    private String openedBy;
    private boolean stated;
    private BigDecimal statedDue;
    private String corrects;
    private LocalDate dueBy;
    private LocalDate deferredUntil;
    private boolean deferred;
    private int proofs;
    private String splitFrom;
    private String lockedBy;
    private boolean lateEntry;
    private LocalDate remindedOn;
    private String ref;
    private String tags;
    private String tagsUsed;
    private String voidReason;
    private String editedBy;
    private Integer dueTerms;
    private Integer batch;

    public Claim(Long id, String sheetId, long personId, BigDecimal amount, LocalDate date, String note,
            ClaimStatus status, String number, BigDecimal due, String openedBy) {
        this.id = id;
        this.sheetId = sheetId;
        this.personId = personId;
        this.amount = amount;
        this.date = date;
        this.note = note;
        this.status = status;
        this.number = number;
        this.due = due;
        this.openedBy = openedBy;
    }

    public Long getId() { return id; }
    public void setId(Long id) { this.id = id; }
    public String getSheetId() { return sheetId; }
    public long getPersonId() { return personId; }
    public void setPersonId(long personId) { this.personId = personId; }
    public BigDecimal getAmount() { return amount; }
    public void setAmount(BigDecimal amount) { this.amount = amount; }
    public LocalDate getDate() { return date; }
    public void setDate(LocalDate date) { this.date = date; }
    public String getNote() { return note; }
    public void setNote(String note) { this.note = note; }
    public ClaimStatus getStatus() { return status; }
    public void setStatus(ClaimStatus status) { this.status = status; }
    /** The claim's number on its sheet, given when it is opened (sheet-wide "7", or within its period "P1-2" / "X-1"); null for a DRAFT, or a claim voided while a DRAFT. A voided claim keeps its number. */
    public String getNumber() { return number; }
    public void setNumber(String number) { this.number = number; }
    /** The due fixed when the claim was settled; null when it has none (not settled, or settled with no rate). */
    public BigDecimal getDue() { return due; }
    public void setDue(BigDecimal due) { this.due = due; }
    /** The user who opened the claim; null while it has not been opened. */
    public String getOpenedBy() { return openedBy; }
    public void setOpenedBy(String openedBy) { this.openedBy = openedBy; }
    /** Whether the claim is bound by its person's last statement to the figure it had then. */
    public boolean isStated() { return stated; }
    public void setStated(boolean stated) { this.stated = stated; }
    /** The figure the last statement bound the claim to; null when unbound, or bound to n/a. */
    public BigDecimal getStatedDue() { return statedDue; }
    public void setStatedDue(BigDecimal statedDue) { this.statedDue = statedDue; }
    /** The number of the SETTLED claim of the same person this correction corrects; null when it is not a correction. */
    public String getCorrects() { return corrects; }
    public void setCorrects(String corrects) { this.corrects = corrects; }
    /** The date the claim is due by, fixed when it was added: its date then plus the terms of its
     *  person's grade in force on that date. Later changes to the terms or the claim's date leave it;
     *  a holiday added on or before it re-fixes it (unless SETTLED or VOID) from its date, with the same terms. */
    public LocalDate getDueBy() { return dueBy; }
    public void setDueBy(LocalDate dueBy) { this.dueBy = dueBy; }
    /** The terms (business days) the claim's due-by was fixed with; a holiday added re-fixes it with these. */
    public Integer getDueTerms() { return dueTerms; }
    public void setDueTerms(Integer dueTerms) { this.dueTerms = dueTerms; }
    /** The date the claim was last deferred until; null when it never was. */
    public LocalDate getDeferredUntil() { return deferredUntil; }
    public void setDeferredUntil(LocalDate deferredUntil) { this.deferredUntil = deferredUntil; }
    /** Whether the claim is deferred now: OPEN, and the sheet's today (as it was when the claim was
     *  read) is before its deferred-until date. A deferred claim counts in no total, is not overdue,
     *  cannot be settled and is left unbound by a statement. */
    public boolean isDeferred() { return deferred && status == ClaimStatus.OPEN; }
    public void setDeferred(boolean deferred) { this.deferred = deferred; }
    /** How many proofs the claim has: a claim whose due is above the sheet's proof threshold on its
     *  date cannot be settled or approved while it has none. */
    public int getProofs() { return proofs; }
    public void setProofs(int proofs) { this.proofs = proofs; }
    /** The number of the claim this one was split off; null when it was not split off one. */
    public String getSplitFrom() { return splitFrom; }
    public void setSplitFrom(String splitFrom) { this.splitFrom = splitFrom; }
    /** The user whose open editor locks the claim for everyone else; null when no editor holds it. */
    public String getLockedBy() { return lockedBy; }
    public void setLockedBy(String lockedBy) { this.lockedBy = lockedBy; }
    /** Whether the claim was added while its period was soft-closed. */
    public boolean isLateEntry() { return lateEntry; }
    public void setLateEntry(boolean lateEntry) { this.lateEntry = lateEntry; }
    /** The last day (sheet-today) a reminder was written for the claim; null when it never was. */
    public LocalDate getRemindedOn() { return remindedOn; }
    public void setRemindedOn(LocalDate remindedOn) { this.remindedOn = remindedOn; }
    /** The claim's external reference, unique on its sheet without regard to case; null when it has none. */
    public String getRef() { return ref; }
    public void setRef(String ref) { this.ref = ref; }
    /** The claim's tags, lower-cased, sorted and comma separated; null when it has none. */
    public String getTags() { return tags; }
    /** Sets the claim's tags, adding them to the tags it has ever carried. */
    public void setTags(String tags) {
        this.tags = tags;
        this.tagsUsed = ClaimRequest.union(tagsUsed, tags);
    }
    /** Every tag the claim has ever carried, in the same form as its tags; null when none. */
    public String getTagsUsed() { return tagsUsed; }
    public void setTagsUsed(String tagsUsed) { this.tagsUsed = tagsUsed; }
    /** The reason from its sheet's list the claim was voided with; null when none was given. */
    public String getVoidReason() { return voidReason; }
    public void setVoidReason(String voidReason) { this.voidReason = voidReason; }
    /** Who last edited the claim (its form or its row's amount entry); null while never edited. */
    public String getEditedBy() { return editedBy; }
    public void setEditedBy(String editedBy) { this.editedBy = editedBy; }
    /** The number of the bulk settle that settled the claim; null when none did. */
    public Integer getBatch() { return batch; }
    public void setBatch(Integer batch) { this.batch = batch; }
    /** Whether the claim is a correction: its amount is negative. Its due has no floor and no late charge. */
    public boolean isCorrection() { return amount.signum() < 0; }
}
package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import net.officefloor.hq.app.holiday.Holidays;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.settings.Settings;

/** The due-by a claim is fixed with when it is added; it also decides the claim's period. */
public final class DueBy {

    private DueBy() {
    }

    /** The due-by of a claim of `person` dated `date`: the terms-th business day after its date,
     *  taking the person's own terms, else the terms of their grade then, else the sheet's terms then,
     *  and skipping every Saturday, Sunday and holiday on the sheet now. */
    public static LocalDate of(Person person, LocalDate date, Settings settings, Holidays holidays) {
        return holidays.businessDaysAfter(person.getSheetId(), date, terms(person, date, settings));
    }

    /** The terms a claim of `person` dated `date` is fixed with: the person's own, else those of their
     *  grade then, else the sheet's then. */
    public static int terms(Person person, LocalDate date, Settings settings) {
        Integer own = person.getTerms();
        return own != null ? own : settings.terms(person.getSheetId(), person.gradeOn(date), date);
    }
}

