import net.officefloor.hq.app.person.People;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.Watches;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.rollup.Snapshot;
import net.officefloor.hq.app.settings.Settings;
import net.officefloor.hq.app.sheet.Sheets;
import net.officefloor.hq.app.voidreason.VoidReasons;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;

/** Settles the selected claims, all or nothing, by the signed-in user. If any of them cannot be
 *  settled (any refusal a single settle would give, or not on the sheet; going PENDING is not a
 *  refusal) none is settled, every one counts as refused and nothing is written. Otherwise each is
 *  settled in list order (people in list order, each person's newest claim first) as a single settle
 *  would be — its own audit line, then the figures it moved — and carries the sheet's next batch
 *  number; after the claims' own lines a BATCH_SETTLED line gives the batch, its count and the
 *  frozen dues of those SETTLED added up. */
public class SettleClaims {
    public void settle(@PathVariable("sheetId") String sheetId, @Val BulkSettle bulk, Claims claims, People people,
            ClaimNumbers numbers, Figures figures, ClosedPeriods closedPeriods, Settings settings, Rollup rollup,
            ClaimLog log, Sheets sheets, Watches watches, Audit audit, VoidReasons voidReasons, Out<BulkSettleResult> result) {
        ClaimStatusChange change = new ClaimStatusChange(ClaimAction.SETTLE, bulk.user());
        ApplyClaimStatus apply = new ApplyClaimStatus();
        RecordClaimStatusChanged record = new RecordClaimStatusChanged();
        List<Claim> all = claims.onSheet(sheetId);
        List<Long> ordered = new ArrayList<>();
        for (Person person : people.onSheet(sheetId)) {
            for (Claim listed : all) {
                if (listed.getPersonId() == person.getId() && bulk.claimIds().contains(listed.getId())) ordered.add(listed.getId());
            }
        }
        int selected = bulk.claimIds().size();
        if (ordered.size() != selected) {
            result.set(new BulkSettleResult(0, selected));
            return;
        }
        // Check every claim first, on a copy that is never saved: one refusal refuses them all.
        for (Long id : ordered) {
            try {
                apply.apply(change, claims.find(sheetId, id), numbers, people, figures, closedPeriods, settings, log, sheets, voidReasons);
            } catch (ClaimStatusRefusedException | PeriodClosedException e) {
                result.set(new BulkSettleResult(0, selected));
                return;
            }
        }
        int batch = claims.nextBatch(sheetId);
        BigDecimal total = BigDecimal.ZERO.setScale(2);
        for (Long id : ordered) {
            Claim claim = claims.find(sheetId, id);
            Snapshot before = rollup.snapshot(sheetId);
            try {
                apply.apply(change, claim, numbers, people, figures, closedPeriods, settings, log, sheets, voidReasons);
            } catch (ClaimStatusRefusedException | PeriodClosedException e) {
                throw new IllegalStateException("A checked claim was refused on settling", e);
            }
            claim.setBatch(batch);
            claims.save(claim);
            record.record(change, claim, people, log, watches, audit);
            rollup.record(sheetId, before, bulk.user());
            if (claim.getStatus() == ClaimStatus.SETTLED && claim.getDue() != null) total = total.add(claim.getDue());
        }
        audit.record("BATCH_SETTLED sheet=" + sheetId + " by=" + bulk.user() + " batch=" + batch
                + " count=" + ordered.size() + " total=" + total.setScale(2, RoundingMode.HALF_UP).toPlainString());
        result.set(new BulkSettleResult(selected, 0));
    }
}
package net.officefloor.hq.app.claim;

import java.math.RoundingMode;
import java.util.List;

/** A claim as the screen sees it: the amount with two decimals, the date as yyyy-mm-dd,
 *  the status as DRAFT, OPEN, PENDING, SETTLED or VOID, the number null when the claim has none, the due
 *  fixed at settling with two decimals, null when it has none (its due is worked out live),
 *  who opened it, null while it has not been opened, whether its person's last statement binds it
 *  and the figure it binds it to (two decimals; null when unbound or bound to n/a), and the number
 *  of the claim a correction corrects (null when it is not a correction), and whether its live
 *  figures round half up (else half to even), by the sheet's policy date, and the due-by fixed when it was added (yyyy-mm-dd), and its status log, oldest first (see {@link ClaimLog}),
 *  and whether it is deferred now and the date it was last deferred until (yyyy-mm-dd; null when it never was), and its proofs count, and the number of the claim it was split off (null when it was not), and the user whose open editor locks it (null when none), and whether it was added while its period was soft-closed, and the last day it was reminded (yyyy-mm-dd; null when it never was), and its external reference (null when none), and its tags (sorted, empty when none) and every tag it has ever carried, and the reason it was voided with (null when none), and its comments, oldest first (see {@link ClaimComments}), and the number of the bulk settle batch that settled it (null when none). */
public record ClaimResponse(long id, long personId, String amount, String date, String note,
        String status, String number, String due, String openedBy, boolean stated, String statedDue, String corrects, boolean halfUp, String dueBy, List<String> log,
        boolean deferred, String deferredUntil, int proofs, String splitFrom, String lockedBy,
        boolean lateEntry, String remindedOn, String ref, List<String> tags, List<String> tagsUsed, String voidReason, List<String> comments, Integer batch) {
    public static ClaimResponse from(Claim claim, Figures figures, List<String> log, List<String> comments) {
        return new ClaimResponse(claim.getId(), claim.getPersonId(), claim.getAmount().toPlainString(),
                claim.getDate().toString(), claim.getNote(), claim.getStatus().name(), claim.getNumber(),
                claim.getDue() != null ? claim.getDue().toPlainString() : null, claim.getOpenedBy(),
                claim.isStated(), claim.getStatedDue() != null ? claim.getStatedDue().toPlainString() : null,
                claim.getCorrects(), figures.rounding(claim) == RoundingMode.HALF_UP,
                claim.getDueBy().toString(), log, claim.isDeferred(),
                claim.getDeferredUntil() != null ? claim.getDeferredUntil().toString() : null, claim.getProofs(), claim.getSplitFrom(), claim.getLockedBy(),
                claim.isLateEntry(), claim.getRemindedOn() != null ? claim.getRemindedOn().toString() : null, claim.getRef(),
                split(claim.getTags()), split(claim.getTagsUsed()), claim.getVoidReason(), comments, claim.getBatch());
    }

    private static List<String> split(String tags) {
        return tags == null ? List.of() : List.of(tags.split(","));
    }
}

