package net.officefloor.hq.app.person;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimStatus;

/** A person on a sheet. `id` is null until the person is first saved. */
public class Person {
    private Long id;
    private final String sheetId;
    private String name;
    /** The person's grades by the date each is in force from; LocalDate.MIN for the first one,
     *  which applies from the beginning of time. */
    private TreeMap<LocalDate, String> grades = new TreeMap<>();
    /** The sheet's today as it was when the person was read (null: the person is new). */
    private LocalDate today;
    /** A grade this save records, from its date (null: the save records none). */
    private DatedGrade newGrade;
    private int version;
    /** The person's own terms in days (null: none). */
    private Integer terms;
    /** Whether this save changes the person's own terms. */
    private boolean termsChanged;
    /** The person's contact (null: none). */
    private String contact;
    /** Whether this save changes the person's contact. */
    private boolean contactChanged;
    private int statementCount;
    private BigDecimal statedTotal;
    private LocalDate statementDate;
    private LocalDate retiredFrom;
    private List<Hold> holds = new ArrayList<>();
    private List<Long> patronIds = new ArrayList<>();

    public Person(Long id, String sheetId, String name, String grade) {
        this(id, sheetId, name, grade, 0);
    }

    public Person(Long id, String sheetId, String name, String grade, int version) {
        this.version = version;
        this.id = id;
        this.sheetId = sheetId;
        this.name = name;
        if (grade != null) this.grades.put(LocalDate.MIN, grade);
    }

    public Long getId() { return id; }
    public void setId(Long id) { this.id = id; }
    public String getSheetId() { return sheetId; }
    public String getName() { return name; }
    public void setName(String name) { this.name = name; }
    /** The grade in force on the sheet's today. */
    public String getGrade() { return today == null ? grades.lastEntry().getValue() : gradeOn(today); }
    /** The grade in force on `date`: the one from the latest date on or before it, the first one
     *  applying from the beginning of time. */
    public String gradeOn(LocalDate date) {
        Map.Entry<LocalDate, String> e = grades.floorEntry(date);
        return e != null ? e.getValue() : grades.firstEntry().getValue();
    }
    /** The first grade the person was given. */
    public String getFirstGrade() { return grades.firstEntry().getValue(); }
    public TreeMap<LocalDate, String> getGrades() { return grades; }
    public void setGrades(TreeMap<LocalDate, String> grades) { this.grades = grades; }
    public void setToday(LocalDate today) { this.today = today; }
    public DatedGrade getNewGrade() { return newGrade; }
    /** Record `grade` from `from` with the next save, replacing any grade from that same date. */
    public void recordGrade(String grade, LocalDate from) {
        this.newGrade = new DatedGrade(grade, from);
        LocalDate key = grades.isEmpty() ? LocalDate.MIN : from;
        grades.put(key, grade);
    }
    /** The person's own terms in days; null when they have none. */
    public Integer getTerms() { return terms; }
    public void setTerms(Integer terms) { this.terms = terms; }
    public boolean isTermsChanged() { return termsChanged; }
    /** Give the person these terms (null: none) with the next save, noting whether they change. */
    public void changeTerms(Integer terms) {
        this.termsChanged = !java.util.Objects.equals(this.terms, terms);
        this.terms = terms;
    }
    /** The person's contact; null when they have none. */
    public String getContact() { return contact; }
    public void setContact(String contact) { this.contact = contact; }
    public boolean isContactChanged() { return contactChanged; }
    /** Give the person this contact (null: none) with the next save, noting whether it changes. */
    public void changeContact(String contact) {
        this.contactChanged = !java.util.Objects.equals(this.contact, contact);
        this.contact = contact;
    }
    /** How many times the person has been saved since added. */
    public int getVersion() { return version; }
    public void setVersion(int version) { this.version = version; }
    /** How many statements have been taken for the person. */
    public int getStatementCount() { return statementCount; }
    public void setStatementCount(int statementCount) { this.statementCount = statementCount; }
    /** The last statement's due-total; null when none was taken or it was n/a. */
    public BigDecimal getStatedTotal() { return statedTotal; }
    public void setStatedTotal(BigDecimal statedTotal) { this.statedTotal = statedTotal; }
    /** The sheet's today when the last statement was taken; null when none was. */
    public LocalDate getStatementDate() { return statementDate; }
    public void setStatementDate(LocalDate statementDate) { this.statementDate = statementDate; }
    /** The date the person is retired from; null when they are not retired. Set at all, they count
     *  as retired at once, whatever the date. */
    public LocalDate getRetiredFrom() { return retiredFrom; }
    public void setRetiredFrom(LocalDate retiredFrom) { this.retiredFrom = retiredFrom; }
    public boolean isRetired() { return retiredFrom != null; }
    /** Whether the sheet's today (as read) has reached the person's retirement date: from then their
     *  OPEN and PENDING claims leave the live totals, as a hold's would. */
    public boolean retiredOut() {
        return retiredFrom != null && today != null && !today.isBefore(retiredFrom);
    }
    /** Whether the person has any hold, whatever its dates. */
    public boolean isHeld() { return !holds.isEmpty(); }
    /** The person's holds, in the order they were added. */
    public List<Hold> getHolds() { return holds; }
    public void setHolds(List<Hold> holds) { this.holds = holds; }
    /** Whether `date` falls within any of the person's holds. */
    public boolean heldOn(LocalDate date) {
        return holds.stream().anyMatch(h -> h.covers(date));
    }
    /** The ids of the people the person has named as patrons, in the order they were named. */
    public List<Long> getPatronIds() { return patronIds; }
    public void setPatronIds(List<Long> patronIds) { this.patronIds = patronIds; }

    /** Whether a claim of the person's counts in the live totals: OPEN, PENDING and SETTLED ones do,
     *  but not a deferred one, nor an OPEN or PENDING one dated within one of the person's holds, nor
     *  one once the sheet's today has reached their retirement date, unless a statement binds it. */
    public boolean counts(Claim claim) {
        return counts(claim, claim.getStatus());
    }

    /** Whether a claim of the person's counts as it would with `status` (null: none, it does not
     *  count): by the live rules above, but with that status in place of the claim's own. */
    public boolean counts(Claim claim, ClaimStatus status) {
        if (status == null) return false;
        if (!status.counts() || claim.isDeferred()) return false;
        if (!status.isOpen() || !(heldOn(claim.getDate()) || retiredOut())) return true;
        return claim.isStated() && status != ClaimStatus.PENDING;
    }

    /** Refuses a claim dated after the person's retirement date. */
    public void refuseRetired(LocalDate claimDate) throws PersonRetiredException {
        if (retiredFrom != null && claimDate.isAfter(retiredFrom)) {
            throw new PersonRetiredException(name, retiredFrom);
        }
    }

    /** A grade in force from a date (null: from the beginning of time). */
    public record DatedGrade(String grade, LocalDate from) {
    }
}
package net.officefloor.hq.app.person;

import java.sql.Date;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.SQLException;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.support.GeneratedKeyHolder;
import org.springframework.stereotype.Repository;

/** The people of each sheet, kept in the order they were added. */
@Repository
public class People {

    private static final String COLUMNS = "SELECT id, sheet_id, name, grade, terms, contact, version, statement_count, stated_total, statement_date, retired_from, "
            + "(SELECT today FROM sheet WHERE sheet.id = person.sheet_id) AS sheet_today FROM person";

    private final JdbcTemplate jdbc;

    public People(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    public List<Person> onSheet(String sheetId) {
        List<Person> people = jdbc.query(COLUMNS + " WHERE sheet_id = ? ORDER BY id",
                People::person,
                sheetId);
        Map<Long, List<Long>> patrons = new HashMap<>();
        jdbc.query("SELECT person_id, patron_id FROM person_patron WHERE sheet_id = ? ORDER BY id",
                (ResultSet rs) -> {
                    patrons.computeIfAbsent(rs.getLong("person_id"), k -> new ArrayList<>()).add(rs.getLong("patron_id"));
                }, sheetId);
        Map<Long, TreeMap<LocalDate, String>> grades = new HashMap<>();
        jdbc.query("SELECT person_id, grade, from_date FROM person_grade WHERE sheet_id = ?",
                (ResultSet rs) -> {
                    grades.computeIfAbsent(rs.getLong("person_id"), k -> new TreeMap<>())
                            .put(fromKey(rs.getDate("from_date")), rs.getString("grade"));
                }, sheetId);
        Map<Long, List<Hold>> holds = new HashMap<>();
        jdbc.query("SELECT person_id, from_date, to_date FROM person_hold WHERE sheet_id = ? ORDER BY id",
                (ResultSet rs) -> {
                    holds.computeIfAbsent(rs.getLong("person_id"), k -> new ArrayList<>()).add(hold(rs));
                }, sheetId);
        for (Person person : people) {
            person.setHolds(holds.getOrDefault(person.getId(), new ArrayList<>()));
            person.setPatronIds(patrons.getOrDefault(person.getId(), new ArrayList<>()));
            TreeMap<LocalDate, String> dated = grades.get(person.getId());
            if (dated != null) person.setGrades(dated);
        }
        return people;
    }

    /** The person with this id on this sheet, or null when there is none. */
    public Person find(String sheetId, long id) {
        return withPatrons(jdbc.query(COLUMNS + " WHERE sheet_id = ? AND id = ?",
                People::person,
                sheetId, id).stream().findFirst().orElse(null));
    }

    /** The person with this id on this sheet, read afresh and locked for the rest of the
     *  transaction, so two statements for one person at once happen one after the other. */
    public Person lock(String sheetId, long id) {
        return withPatrons(jdbc.query(COLUMNS + " WHERE sheet_id = ? AND id = ? FOR UPDATE", People::person, sheetId, id)
                .stream().findFirst().orElse(null));
    }

    /** The person on this sheet with this name (matched as names are kept unique: without the
     *  spaces around it and in any case), or null when there is none. */
    public Person named(String sheetId, String name) {
        return withPatrons(jdbc.query(COLUMNS + " WHERE sheet_id = ? AND name_key = LOWER(TRIM(?))", People::person,
                sheetId, name).stream().findFirst().orElse(null));
    }

    /** Whether another person on this sheet (not `exceptId`, which may be null) already has this name. */
    public boolean nameTaken(String sheetId, String name, Long exceptId) {
        Integer n = jdbc.queryForObject(
                "SELECT COUNT(*) FROM person WHERE sheet_id = ? AND name_key = LOWER(TRIM(?)) AND id <> ?",
                Integer.class, sheetId, name, exceptId == null ? -1L : exceptId);
        return n != null && n > 0;
    }

    /** Whether another person on this sheet (not `exceptId`, which may be null) already has this contact. */
    public boolean contactTaken(String sheetId, String contact, Long exceptId) {
        Integer n = jdbc.queryForObject(
                "SELECT COUNT(*) FROM person WHERE sheet_id = ? AND contact = ? AND id <> ?",
                Integer.class, sheetId, contact, exceptId == null ? -1L : exceptId);
        return n != null && n > 0;
    }

    /** Insert a new person (assigning its id) or update an existing one, if it is still at the
     *  version it was loaded at; false (nothing written) when someone has saved it since. */
    public boolean save(Person person) {
        if (person.getId() != null) {
            int n = jdbc.update("UPDATE person SET name = ?, terms = ?, contact = ?, version = version + 1 WHERE id = ? AND version = ?",
                    person.getName(), person.getTerms(), person.getContact(), person.getId(), person.getVersion());
            if (n == 0) return false;
            person.setVersion(person.getVersion() + 1);
            Person.DatedGrade dated = person.getNewGrade();
            if (dated != null) saveGrade(person, dated);
            return true;
        }
        GeneratedKeyHolder keys = new GeneratedKeyHolder();
        jdbc.update(con -> {
            PreparedStatement ps = con.prepareStatement(
                    "INSERT INTO person (sheet_id, name, grade, terms, contact) VALUES (?, ?, ?, ?, ?)", new String[] { "id" });
            ps.setString(1, person.getSheetId());
            ps.setString(2, person.getName());
            ps.setString(3, person.getFirstGrade());
            ps.setObject(4, person.getTerms(), java.sql.Types.INTEGER);
            ps.setString(5, person.getContact());
            return ps;
        }, keys);
        person.setId(keys.getKey().longValue());
        // The first grade a person is given applies from the beginning of time.
        saveGrade(person, new Person.DatedGrade(person.getFirstGrade(), null));
        return true;
    }

    /** Record a statement taken for the person (their count, last due-total and date). Not an edit:
     *  the person's version is untouched, so an editor open on them can still save. */
    public void saveStatement(Person person) {
        jdbc.update("UPDATE person SET statement_count = ?, stated_total = ?, statement_date = ? WHERE id = ?",
                person.getStatementCount(), person.getStatedTotal(), Date.valueOf(person.getStatementDate()),
                person.getId());
        jdbc.update("INSERT INTO person_statement (sheet_id, person_id, seq, stated_total, statement_date) VALUES (?, ?, ?, ?, ?)",
                person.getSheetId(), person.getId(), person.getStatementCount(), person.getStatedTotal(),
                Date.valueOf(person.getStatementDate()));
    }

    /** Cancel the person's last statement: their count goes down by one and they show the one
     *  before it (its due-total and date), or none. Not an edit: the person's version is untouched. */
    public void cancelStatement(Person person) {
        jdbc.update("DELETE FROM person_statement WHERE person_id = ? AND seq >= ?",
                person.getId(), person.getStatementCount());
        int count = person.getStatementCount() - 1;
        List<Object[]> before = jdbc.query(
                "SELECT stated_total, statement_date FROM person_statement WHERE person_id = ? AND seq = ?",
                (rs, n) -> new Object[] { rs.getBigDecimal(1), rs.getDate(2) }, person.getId(), count);
        person.setStatementCount(count);
        person.setStatedTotal(before.isEmpty() ? null : (java.math.BigDecimal) before.get(0)[0]);
        person.setStatementDate(before.isEmpty() ? null : ((Date) before.get(0)[1]).toLocalDate());
        jdbc.update("UPDATE person SET statement_count = ?, stated_total = ?, statement_date = ? WHERE id = ?",
                count, person.getStatedTotal(),
                person.getStatementDate() != null ? Date.valueOf(person.getStatementDate()) : null, person.getId());
    }

    /** Record the person's retirement date. Not an edit: the person's version is untouched. */
    public void saveRetirement(Person person) {
        jdbc.update("UPDATE person SET retired_from = ? WHERE id = ?",
                person.getRetiredFrom() != null ? Date.valueOf(person.getRetiredFrom()) : null, person.getId());
    }

    /** Add a hold to the person. Not an edit: the person's version is untouched. */
    public void addHold(Person person, Hold hold) {
        jdbc.update("INSERT INTO person_hold (sheet_id, person_id, from_date, to_date) VALUES (?, ?, ?, ?)",
                person.getSheetId(), person.getId(), Date.valueOf(hold.from()),
                hold.to() != null ? Date.valueOf(hold.to()) : null);
        person.getHolds().add(hold);
    }

    /** Name `patron` as one of the person's patrons. Not an edit: the person's version is untouched. */
    public void addPatron(Person person, Person patron) {
        jdbc.update("INSERT INTO person_patron (sheet_id, person_id, patron_id) VALUES (?, ?, ?)",
                person.getSheetId(), person.getId(), patron.getId());
        person.getPatronIds().add(patron.getId());
    }

    /** Record the person's grade from its date, replacing the one they had from that date. */
    private void saveGrade(Person person, Person.DatedGrade dated) {
        Date from = dated.from() != null ? Date.valueOf(dated.from()) : null;
        jdbc.update("DELETE FROM person_grade WHERE person_id = ? AND from_date IS NOT DISTINCT FROM ?",
                person.getId(), from);
        jdbc.update("INSERT INTO person_grade (sheet_id, person_id, grade, from_date) VALUES (?, ?, ?, ?)",
                person.getSheetId(), person.getId(), dated.grade(), from);
    }

    private static LocalDate fromKey(Date from) {
        return from != null ? from.toLocalDate() : LocalDate.MIN;
    }

    /** The person (may be null) with their patrons' ids and dated grades read in. */
    private Person withPatrons(Person person) {
        if (person != null) {
            TreeMap<LocalDate, String> grades = new TreeMap<>();
            jdbc.query("SELECT grade, from_date FROM person_grade WHERE person_id = ?",
                    (ResultSet rs) -> {
                        grades.put(fromKey(rs.getDate("from_date")), rs.getString("grade"));
                    }, person.getId());
            if (!grades.isEmpty()) person.setGrades(grades);
            person.setHolds(new ArrayList<>(jdbc.query(
                    "SELECT from_date, to_date FROM person_hold WHERE person_id = ? ORDER BY id",
                    (rs, i) -> hold(rs), person.getId())));
            person.setPatronIds(new ArrayList<>(jdbc.queryForList(
                    "SELECT patron_id FROM person_patron WHERE person_id = ? ORDER BY id", Long.class, person.getId())));
        }
        return person;
    }

    private static Hold hold(ResultSet rs) throws SQLException {
        Date to = rs.getDate("to_date");
        return new Hold(rs.getDate("from_date").toLocalDate(), to != null ? to.toLocalDate() : null);
    }

    private static Person person(ResultSet rs, int i) throws SQLException {
        Person person = new Person(rs.getLong("id"), rs.getString("sheet_id"), rs.getString("name"),
                rs.getString("grade"), rs.getInt("version"));
        person.setTerms(rs.getObject("terms", Integer.class));
        person.setContact(rs.getString("contact"));
        person.setStatementCount(rs.getInt("statement_count"));
        person.setStatedTotal(rs.getBigDecimal("stated_total"));
        Date date = rs.getDate("statement_date");
        person.setStatementDate(date != null ? date.toLocalDate() : null);
        Date retired = rs.getDate("retired_from");
        person.setRetiredFrom(retired != null ? retired.toLocalDate() : null);
        Date today = rs.getDate("sheet_today");
        person.setToday(today != null ? today.toLocalDate() : LocalDate.now());
        return person;
    }
}
package net.officefloor.hq.app.person;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.HashMap;
import java.util.Map;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.Claims;
import net.officefloor.hq.app.claim.Figures;
import net.officefloor.hq.app.rate.Rates;
import net.officefloor.hq.app.settings.Settings;
import net.officefloor.hq.app.sheet.AsOf;
import net.officefloor.hq.app.sheet.InvalidSheetRequestException;
import net.officefloor.hq.app.sheet.Sheets;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** Takes the person's statement: their due-total now, the sum of their counting claims' figures
 *  with any late charges, each at least the floor (n/a when there is no rate today and none has a figure), at most the sheet's cap, dated the sheet's today. Every claim
 *  of theirs that counts (not an OPEN one dated within one of their holds) is bound to its rate figure now, without its late charge or the floor; every other one is unbound.
 *  Taken as of a date (on or before the sheet's today), all of it is worked out on the sheet as it
 *  stood at the end of that date (see {@link AsOf}): the claims that counted then are bound to their
 *  figures then, and the statement is dated that date. Refused: a date after the sheet's today, or
 *  one the person was not yet on the sheet. */
public class TakeStatement {
    public void take(@Val StatementRequest request, @Val Person person, Claims claims, Figures figures,
            Rates rates, Sheets sheets, Settings settings, People people, AsOf asOf, Out<Statement> statement)
            throws InvalidSheetRequestException {
        LocalDate date = asOfDate(request);
        String sheetId = person.getSheetId();
        if (date != null && date.isAfter(sheets.today(sheetId))) {
            throw new InvalidSheetRequestException("A statement cannot be taken as of a date after the sheet's today");
        }
        Person locked = people.lock(sheetId, person.getId());
        person.setStatementCount(locked.getStatementCount());
        Taken taken = date == null ? work(person, claims, figures, rates, sheets, settings)
                : asOf.at(sheetId, date, () -> {
                    Person then = people.find(sheetId, person.getId());
                    return then == null ? null : work(then, claims, figures, rates, sheets, settings);
                });
        if (taken == null) {
            throw new InvalidSheetRequestException("This person was not on the sheet on " + date);
        }
        for (Claim claim : claims.ofPerson(sheetId, person.getId())) {
            boolean bound = taken.bound().containsKey(claim.getId());
            claim.setStated(bound);
            claim.setStatedDue(bound ? taken.bound().get(claim.getId()) : null);
            claims.save(claim);
        }
        person.setStatementCount(person.getStatementCount() + 1);
        person.setStatedTotal(taken.dueTotal());
        person.setStatementDate(taken.date());
        people.saveStatement(person);
        statement.set(new Statement(taken.dueTotal(), taken.bound().size(), request.user(), date));
    }

    /** The statement of the person as the sheet stands (live, or as of a date): the figure each
     *  counting claim is bound to, by id, and their due-total, dated the sheet's today. */
    private static Taken work(Person person, Claims claims, Figures figures, Rates rates, Sheets sheets,
            Settings settings) {
        String sheetId = person.getSheetId();
        BigDecimal total = BigDecimal.ZERO.setScale(2);
        boolean any = false;
        Map<Long, BigDecimal> bound = new HashMap<>();
        for (Claim claim : claims.ofPerson(sheetId, person.getId())) {
            if (person.counts(claim)) {
                // The statement binds the rate figure; the late charge and floor on top keep following today.
                bound.put(claim.getId(), figures.figure(claim, person.gradeOn(claim.getDate())));
                BigDecimal figure = figures.due(claim, person.gradeOn(claim.getDate()));
                if (figure != null) {
                    total = total.add(figure);
                    any = true;
                }
            }
        }
        LocalDate today = sheets.today(sheetId);
        BigDecimal dueTotal = !any && rates.pct(sheetId, person.gradeOn(today), today) == null ? null
                : settings.capped(sheetId, total);
        return new Taken(bound, dueTotal, today);
    }

    /** The date the statement is taken as of; null when none was given. */
    private static LocalDate asOfDate(StatementRequest request) throws InvalidSheetRequestException {
        String text = request.asOf();
        if (text == null || text.isBlank()) return null;
        try {
            return LocalDate.parse(text.trim());
        } catch (DateTimeParseException e) {
            throw new InvalidSheetRequestException("Not a date: " + text);
        }
    }

    private record Taken(Map<Long, BigDecimal> bound, BigDecimal dueTotal, LocalDate date) {
    }
}

