/** Gives each selected person the grade from the from-date, in list order, exactly as saving the
 *  person form would (their name and terms as they are): each audited PERSON_EDITED, then the
 *  figures it moved. One not on the sheet is skipped. A viewer, or anyone on an archived sheet,
 *  grades no one. */
public class GradePeople {
    public void grade(@PathVariable("sheetId") String sheetId, @Val BulkGrade bulk, People people, Sheets sheets,
            Rollup rollup, Settings settings, Audit audit, Out<BulkGradeResult> result) {
        if (sheets.archived(sheetId) || settings.role(sheetId, bulk.user()) == Role.VIEWER) {
            result.set(new BulkGradeResult(0));
            return;
        }
        ApplyPerson apply = new ApplyPerson();
        SavePerson save = new SavePerson();
        RecordPersonEdited record = new RecordPersonEdited();
        int graded = 0;
        for (Person listed : people.onSheet(sheetId)) {
            if (!bulk.personIds().contains(listed.getId())) continue;
            Person person = people.find(sheetId, listed.getId());
            if (person == null) continue;
            PersonRequest request = new PersonRequest(person.getName(), bulk.grade(), bulk.user(), null, bulk.from(),
                    person.getTerms() == null ? "" : String.valueOf(person.getTerms()),
                    person.getContact());
            Snapshot before = rollup.snapshot(sheetId);
            try {
                apply.apply(request, person, people, sheets);
                save.save(person, people);
            } catch (InvalidSheetRequestException | PersonConflictException e) {
                continue;
            }
            record.record(request, person, audit);
            rollup.record(sheetId, before, bulk.user());
            graded++;
        }
        result.set(new BulkGradeResult(graded));
    }
}
=== person/ApplyPerson.java


/** Changes the person's name and records the form's grade from its from-date (blank: the sheet's
 *  today), keeping the grades already recorded — except that a save leaving the grade as the row
 *  showed it (the one in force on the sheet's today), with the from-date blank, records none.
 *  The person's own terms and contact become the form's (blank: none). */
public class ApplyPerson {
    public void apply(@Val PersonRequest request, @Val Person person, People people, Sheets sheets)
            throws InvalidSheetRequestException, PersonConflictException {
        if (request.version() != null && request.version() != person.getVersion()) {
            throw new PersonConflictException(PersonResponse.from(person));
        }
        if (people.nameTaken(person.getSheetId(), request.name(), person.getId())) {
            throw new InvalidSheetRequestException("The name is already in use on this sheet");
        }
        if (request.contactKey() != null
                && people.contactTaken(person.getSheetId(), request.contactKey(), person.getId())) {
            throw new InvalidSheetRequestException("The contact is already in use on this sheet");
        }
        person.setName(request.name());
        person.changeContact(request.contactKey());
        person.changeTerms(request.termsDays());
        var from = request.gradeFromDate();
        var today = sheets.today(person.getSheetId());
        person.setToday(today);
        if (from == null && request.grade().equals(person.getGrade())) return;
        person.recordGrade(request.grade(), from != null ? from : today);
    }
}
