=== claim/ClaimRequest.java


/** Body of a claim add or edit, as typed: the amount, the date (blank for the sheet's today),
 *  the note, the number of the claim it corrects (blank for none), who makes the change and the
 *  external reference (blank for none) and the tags, comma separated (blank for none). */
public record ClaimRequest(String amount, String date, String note, String corrects, String user, String ref, String tags) {
    /** Up to two decimals; negative only for a correction. */
    private static final Pattern AMOUNT = Pattern.compile("-?\\d+(\\.\\d{1,2})?");
    private static final Pattern NUMBER = Pattern.compile("\\d+|.+-\\d+");

    /** The request's values as the claim rules accept them, or refused. A negative amount is a
     *  correction and must name the number of the claim it corrects; any other claim corrects none. */
    public static ClaimValues checked(ClaimRequest request) throws InvalidSheetRequestException {
        String amount = request == null || request.amount() == null ? "" : request.amount().trim();
        if (!AMOUNT.matcher(amount).matches()) {
            throw new InvalidSheetRequestException("The amount must be a number with up to two decimals");
        }
        BigDecimal value = new BigDecimal(amount).setScale(2);
        String rawCorrects = request.corrects() == null ? "" : request.corrects().trim();
        String corrects = null;
        if (value.signum() < 0) {
            if (!NUMBER.matcher(rawCorrects).matches()) {
                throw new InvalidSheetRequestException("A negative amount must name the number of the settled claim it corrects");
            }
            corrects = rawCorrects;
        }
        String rawDate = request.date() == null ? "" : request.date().trim();
        LocalDate date = null;
        if (!rawDate.isEmpty()) {
            try {
                date = LocalDate.parse(rawDate);
            } catch (DateTimeParseException e) {
                throw new InvalidSheetRequestException("Not a date (yyyy-mm-dd): " + rawDate);
            }
        }
        String note = request.note() == null ? "" : request.note();
        String ref = request.ref() == null || request.ref().isBlank() ? null : request.ref().trim();
        return new ClaimValues(value, date, note, corrects, request.user(), ref, tags(request.tags()));
    }

    /** Comma separated tags as stored: each trimmed and lower-cased, blanks and repeats dropped,
     *  sorted, joined by commas; null when there are none. */
    static String tags(String raw) {
        if (raw == null) return null;
        TreeSet<String> tags = new TreeSet<>();
        for (String tag : raw.split(",")) {
            String t = tag.trim().toLowerCase(Locale.ROOT);
            if (!t.isEmpty()) tags.add(t);
        }
        return tags.isEmpty() ? null : String.join(",", tags);
    }

    /** The union of two stored tag lists, in the same form. */
    static String union(String a, String b) {
        return tags((a == null ? "" : a) + "," + (b == null ? "" : b));
    }
}
=== claim/ValidatePasteClaims.java


/** Splits the paste into lines of name,amount,date,note (the note may hold commas, the date may be
 *  blank, the note absent) and checks each by the claim form's rules; blank lines are skipped. A
 *  note ending in ` #<reference>` gives the claim that reference (not part of the note); a reference
 *  repeated within the paste, without regard to case, refuses it. */
public class ValidatePasteClaims {
    /** A note ending in a space, a hash and the reference. */
    private static final Pattern REF = Pattern.compile("(.*) #(.+)");

    public void validate(@RequestBody PasteClaimsRequest request, Out<PastedClaims> body, Out<Actor> actor)
            throws InvalidSheetRequestException {
        String user = request == null ? null : request.user();
        String text = request == null || request.text() == null ? "" : request.text();
        List<PastedLine> lines = new ArrayList<>();
        Set<String> refs = new HashSet<>();
        int n = 0;
        for (String raw : text.split("\\r?\\n")) {
            n++;
            if (raw.isBlank()) continue;
            String[] f = raw.split(",", 4);
            if (f.length < 2 || f[0].isBlank()) {
                throw new InvalidSheetRequestException("Line " + n + ": a name and an amount are needed");
            }
            String note = f.length > 3 ? f[3] : "";
            String ref = null;
            Matcher tagged = REF.matcher(note.trim());
            if (tagged.matches() && !tagged.group(2).isBlank()) {
                note = tagged.group(1);
                ref = tagged.group(2);
            }
            ClaimValues values;
            try {
                values = ClaimRequest.checked(new ClaimRequest(f[1], f.length > 2 ? f[2] : "", note, null, user, ref, null));
            } catch (InvalidSheetRequestException e) {
                throw new InvalidSheetRequestException("Line " + n + ": " + e.getMessage());
            }
            if (values.ref() != null && !refs.add(values.ref().toLowerCase(Locale.ROOT))) {
                throw new InvalidSheetRequestException("Line " + n + ": the reference is repeated in the paste: " + values.ref());
            }
            lines.add(new PastedLine(f[0].trim(), values));
        }
        if (lines.isEmpty()) throw new InvalidSheetRequestException("Paste at least one line of name,amount,date,note");
        actor.set(new Actor(user));
        body.set(new PastedClaims(lines, user));
    }
}
=== sheet/AsOf.java


/** A sheet as it stood at the end of a date: every change made while the sheet's today was on or
 *  before that date counts, every later change does not, and that date stands in for the sheet's
 *  today. The sheet's rows are rebuilt from the change history (see {@link History}) into the asof
 *  schema, and the work runs against it in place of the live tables, so every rule reads the sheet
 *  as it was. The work must only read: what it writes is thrown away. */
@Service
public class AsOf {

    /** The tables of a sheet's data (keyed by sheet_id) kept in asof_hist and rebuilt into asof. */
    static final List<String> TABLES = List.of("CLAIM", "PERSON", "PERSON_GRADE", "PERSON_HOLD", "PERSON_PATRON",
            "PERSON_WATCH", "PERSON_STATEMENT", "PERIOD", "PERIOD_PERSON_TOTAL", "PERIOD_NUMBER", "RATE",
            "SHEET_SETTING", "SHEET_SETTING_DATED", "SHEET_ROLE", "SHEET_PERMISSION", "SHEET_DELEGATION",
            "CLAIM_LOG", "SHEET_GRADE_TERMS", "SHEET_HOLIDAY", "SHEET_VOID_REASON", "CLAIM_COMMENT");

    private final JdbcTemplate jdbc;
    private final TransactionTemplate transactions;
    private final Map<String, List<String>> columns = new HashMap<>();

    public AsOf(JdbcTemplate jdbc, PlatformTransactionManager transactionManager) {
        this.jdbc = jdbc;
        this.transactions = new TransactionTemplate(transactionManager);
    }

    /** Run `work` against the sheet as it stood at the end of `date`. It runs in a transaction of its
     *  own, on one connection, which is rolled back: the rebuilt rows are never kept. */
    public <T> T at(String sheetId, LocalDate date, Supplier<T> work) {
        return transactions.execute(status -> {
            status.setRollbackOnly();
            // One rebuild of the sheet at a time.
            jdbc.query("SELECT id FROM PUBLIC.sheet WHERE id = ? FOR UPDATE", (RowCallbackHandler) rs -> {}, sheetId);
            rebuild(sheetId, date);
            schema("ASOF");
            try {
                return work.get();
            } finally {
                schema("PUBLIC");
            }
        });
    }

    /** What a screen reads: `work` on the sheet as it stood at the end of the as-of date given (see
     *  {@link #at}), or on the live sheet when none is given. Refused: an as-of that is not a date. */
    public <T> T view(String sheetId, String asOfText, Supplier<T> work) throws InvalidSheetRequestException {
        if (asOfText == null || asOfText.isBlank()) return work.get();
        LocalDate date;
        try {
            date = LocalDate.parse(asOfText.trim());
        } catch (DateTimeParseException e) {
            throw new InvalidSheetRequestException("Not a date: " + asOfText);
        }
        return at(sheetId, date, work);
    }

    private void rebuild(String sheetId, LocalDate date) {
        jdbc.update("DELETE FROM ASOF.sheet WHERE id = ?", sheetId);
        jdbc.update("INSERT INTO ASOF.sheet SELECT * FROM PUBLIC.sheet WHERE id = ?", sheetId);
        // Archived only by an archive made by then.
        jdbc.update("UPDATE ASOF.sheet SET today = ?, archived = archived AND (archived_on IS NULL OR archived_on <= ?) "
                + "WHERE id = ?", Date.valueOf(date), Date.valueOf(date), sheetId);
        for (String table : TABLES) {
            List<String> cols = columns(table);
            String names = '"' + String.join("\", \"", cols) + '"';
            // The rows as they stood: each change made by then removes or adds one, in the order made.
            Map<List<Object>, Integer> rows = new LinkedHashMap<>();
            jdbc.query("SELECT " + names + ", H_OP FROM ASOF_HIST.\"" + table + "\" WHERE sheet_id = ? "
                    + "AND (H_MADE_ON IS NULL OR H_MADE_ON <= ?) ORDER BY H_SEQ", (RowCallbackHandler) rs -> {
                        List<Object> row = new ArrayList<>(cols.size());
                        for (int i = 1; i <= cols.size(); i++) row.add(rs.getObject(i));
                        rows.merge(row, "I".equals(rs.getString(cols.size() + 1)) ? 1 : -1, Integer::sum);
                    }, sheetId, Date.valueOf(date));
            jdbc.update("DELETE FROM ASOF.\"" + table + "\" WHERE sheet_id = ?", sheetId);
            String insert = "INSERT INTO ASOF.\"" + table + "\" (" + names + ") VALUES ("
                    + "?, ".repeat(cols.size() - 1) + "?)";
            List<Object[]> batch = new ArrayList<>();
            rows.forEach((row, n) -> {
                for (int i = 0; i < n; i++) batch.add(row.toArray());
            });
            if (!batch.isEmpty()) jdbc.batchUpdate(insert, batch);
        }
    }

    private List<String> columns(String table) {
        synchronized (columns) {
            return columns.computeIfAbsent(table, t -> jdbc.queryForList("SELECT COLUMN_NAME FROM INFORMATION_SCHEMA.COLUMNS "
                    + "WHERE TABLE_SCHEMA = 'ASOF' AND TABLE_NAME = ? ORDER BY ORDINAL_POSITION", String.class, t));
        }
    }

    private void schema(String schema) {
        jdbc.execute((ConnectionCallback<Void>) (Connection c) -> {
            c.setSchema(schema);
            return null;
        });
    }
}

