 * What is due on `amount` (two decimals) at `pct` percent: amount times pct divided by 100,
 * rounded to two decimals (half up with `halfUp`, else half to even), worked in whole numbers so it
 * is exact. In cents, or null when there is no rate.
 */
export function dueCents(amount: string, pct: string | undefined, halfUp = false): bigint | null {
  if (pct === undefined) return null;
  // cents * hundredths-of-a-percent is in ten-thousandths of a cent.
  // Rounded on its size, so a negative amount (a correction) rounds like a positive one.
  const product = hundredths(amount) * hundredths(pct);
  const abs = product < 0n ? -product : product;
  const rounded = roundTenThousandths(abs, halfUp);
  return product < 0n ? -rounded : rounded;
}

/** A size in ten-thousandths of a cent, rounded to whole cents: half up with `halfUp`, else half to even. */
export function roundTenThousandths(abs: bigint, halfUp: boolean): bigint {
  const whole = abs / 10000n;
  const rest = abs % 10000n;
  return rest > 5000n || (rest === 5000n && (halfUp || whole % 2n === 1n)) ? whole + 1n : whole;
}

/** A due in cents as shown: two decimals, or n/a when there is no rate. */
export function showDue(cents: bigint | null): string {
  return cents === null ? 'n/a' : format(cents);
}

/** Dues added up, skipping the n/a ones. */
export function totalDue(dues: Array<bigint | null>): string {
  return format(dues.reduce<bigint>((sum, d) => (d === null ? sum : sum + d), 0n));
}

/** The figures (n/a skipped) added up, leaving out the single highest and lowest when three or more. */
export function trimmedTotal(dues: Array<bigint | null>): string {
  const figures = dues.filter((d): d is bigint => d !== null).sort((a, b) => (a < b ? -1 : a > b ? 1 : 0));
  return totalDue(figures.length >= 3 ? figures.slice(1, -1) : figures);
}
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { claimDueCents, type Claim, type ClaimStatus, type Late } from '../claims/useClaims';
import { gradeOn, heldOn, type Person } from '../people/usePeople';
import { hundredths, rateOn, totalDue, type Rate } from '../rates/useRates';
import type { FloorOn } from '../settings/useSettings';
import { asOfKey, asOfPath, useAsOf } from '../asof/useAsOf';

/** A period as the server sends it: its name, its from and to dates (yyyy-mm-dd), inclusive, whether
 *  it is closed and, when it is, the due-total fixed when it was closed and each person's (by person
 *  id; a person not in it, added since, has 0.00), and whether it is only soft-closed: its figures
 *  are fixed as by a close, but claims dated in it can still be changed. */
export type Period = {
  name: string;
  from: string;
  to: string;
  closed: boolean;
  closedTotal: string | null;
  closedPersonTotals: Record<string, string>;
  soft: boolean;
};

export const periodsKey = (sheet: string) => ['sheet', sheet, 'periods'] as const;

/** The sheet's periods, by from-date, re-read whenever the sheet is loaded. */
export function usePeriods(sheet: string) {
  const [asOf] = useAsOf();
  return useQuery({
    queryKey: asOfKey(periodsKey(sheet), asOf),
    queryFn: () => getJson<Period[]>(asOfPath(`/api/sheets/${encodeURIComponent(sheet)}/periods`, asOf)),
    staleTime: 0,
    gcTime: 0,
  });
}

/** A date the server accepts: yyyy-mm-dd. */
export const DATE = /^\d{4}-\d{2}-\d{2}$/;

/** The period whose dates contain `date` (yyyy-mm-dd), or undefined when none does. Periods never
 *  overlap, so there is at most one. */
export function periodOf(periods: Period[], date: string): Period | undefined {
  return periods.find((p) => p.from <= date && date <= p.to);
}

/** The status a claim had at the end of `date` (yyyy-mm-dd), as its status log records it: the last
 *  line dated on or before it; null when the claim was added after it. A claim kept before the log
 *  began (no lines) goes by its status now. */
export function statusAt(claim: Claim, date: string): ClaimStatus | null {
  if (claim.log.length === 0) return claim.status;
  let status: ClaimStatus | null = null;
  for (const line of claim.log) {
    const m = /^(\S+) by .* on (\d{4}-\d{2}-\d{2}) due=/.exec(line);
    if (m && m[2] <= date) status = m[1] as ClaimStatus;
  }
  return status;
}

/** Whether a person's claim counts in a period's due-total: due by in it (its due-by as fixed when it was added), and counted (OPEN, PENDING
 *  or SETTLED) by the status it had at the end of the period's last day — not a deferred one, nor
 *  one open then and dated within the person's hold (or the person's once the sheet's today reaches
 *  their retirement date), unless a statement binds it. */
function countsIn(period: Period, person: Person, claim: Claim, today: string): boolean {
  if (claim.personId !== person.id || periodOf([period], claim.dueBy) === undefined || claim.deferred) return false;
  const status = statusAt(claim, period.to);
  if (status !== 'OPEN' && status !== 'PENDING' && status !== 'SETTLED') return false;
  if (status === 'SETTLED' || !heldOn(person, claim.date, today)) return true;
  return claim.stated && status !== 'PENDING';
}

/** A person's due-total for a period, in cents: the one fixed when the period was closed (0 for a
 *  person added since), else the dues, as shown now, of their claims that count in it (see
 *  `countsIn`: by the status each had at the period's end), n/a ones skipped. */
export function personPeriodDueCents(period: Period, person: Person, claims: Claim[], rates: Rate[], floor: FloorOn, late: Late, today: string): bigint {
  if (period.closed) {
    const fixed = period.closedPersonTotals?.[String(person.id)];
    return fixed === undefined ? 0n : hundredths(fixed);
  }
  return claims
    .filter((c) => countsIn(period, person, c, today))
    .reduce<bigint>((sum, c) => sum + (claimDueCents(c, floor, rateOn(rates, gradeOn(person, c.date), c.date), late) ?? 0n), 0n);
}

/** A period's due-total: everyone's due-total for it added up. */
export function periodDue(period: Period, claims: Claim[], people: Person[], rates: Rate[], floor: FloorOn, late: Late, today: string): string {
  return totalDue(people.map((p) => personPeriodDueCents(period, p, claims, rates, floor, late, today)));
}

