/**
 * The sheet's totals: its claimed-total, everyone's counted (OPEN or SETTLED) claims added up
 * (not OPEN ones dated within their person's hold, unless stated), and its due-total, everyone's due-total
 * added up (a person whose due-total is n/a is skipped), and how many of the claims that count are
 * overdue, with their dues added up. Both due and overdue totals leave out the single highest and
 * lowest person's figure when three or more people have one. Its settled-total and open-total are
 * everyone's due-total before the cap split into SETTLED and OPEN-or-PENDING claims, simply added up. One place, so every screen repeating a total shows the same figure.
 */
export function useSheetTotals(sheet: string) {
  const { data: all = [] } = useClaims(sheet);
  const { data: people = [] } = usePeople(sheet);
  const { data: rates = [] } = useRates(sheet);
  const today = useSheetToday(sheet);
  const claims = live(all, heldOnBy(people, today));
  const floor = useFloor(sheet);
  const late = useLate(sheet);
  const cap = useCap(sheet);
  const dues = people.map((p) =>
    personDueCents(claims.filter((c) => c.personId === p.id), floor, rateOn(rates, gradeOn(p, today), today), (d) => rateOn(rates, gradeOn(p, d), d), late, cap),
  );
  // Everyone's due-total before the cap, split into its SETTLED and its OPEN-and-PENDING part.
  const part = (keep: (c: (typeof claims)[number]) => boolean) =>
    people.map((p) =>
      personDueCents(claims.filter((c) => c.personId === p.id && keep(c)), floor, rateOn(rates, gradeOn(p, today), today), (d) => rateOn(rates, gradeOn(p, d), d), late),
    );
  const over = people.map((p) =>
    overdueFigures(claims.filter((c) => c.personId === p.id), late, floor, (d) => rateOn(rates, gradeOn(p, d), d)),
  );
  return {
    claimedTotal: claimed(claims),
    dueTotal: trimmedTotal(dues),
    settledTotal: totalDue(part((c) => c.status === 'SETTLED')),
    openTotal: totalDue(part(isOpen)),
    overdueCount: over.reduce((n, o) => n + o.count, 0),
    overdueTotal: trimmedTotal(over.map((o) => o.cents)),
  };
}

/** The sheet's totals (see useSheetTotals). */
function ClaimedTotal({ sheet }: { user: string; sheet: string }) {
  const { claimedTotal, dueTotal, settledTotal, openTotal, overdueCount, overdueTotal } = useSheetTotals(sheet);
  return (
    <>
      <p>
        Claimed in total: <strong data-testid="rollup-claimed-total">{claimedTotal}</strong>
      </p>
      <p>
        Due in total: <strong data-testid="rollup-due-total">{dueTotal}</strong>
      </p>
      <p>
        Settled in total: <strong data-testid="rollup-settled-total">{settledTotal}</strong>, open in total:{' '}
        <strong data-testid="rollup-open-total">{openTotal}</strong>
      </p>
      <p>
        Overdue: <strong data-testid="rollup-overdue-count">{overdueCount}</strong>, due{' '}
        <strong data-testid="rollup-overdue-total">{overdueTotal}</strong>
      </p>
    </>
  );
}

export const contribution = SheetPanels.fill({ order: 20, Component: ClaimedTotal });

/**
 * The sheet's header, shown at all times: how many people are on the sheet (retired ones
 * included), how many claims have each status (as the summary counts them), and the sheet's
 * due-total and overdue-total (as the totals work them out).
 */
function SheetHeader({ sheet }: { user: string; sheet: string }) {
  const { data: all = [] } = useClaims(sheet);
  const { data: everyone = [] } = usePeople(sheet);
  const { dueTotal, overdueTotal } = useSheetTotals(sheet);
  return (
    <header data-testid="sheet-header">
      <span>
        People: <strong data-testid="header-people-count">{everyone.length}</strong>
      </span>
      {STATUSES.map((s) => (
        <span key={s}>
          {' '}
          {s}: <strong data-testid={`header-claims-${s}-count`}>{all.filter((c) => c.status === s).length}</strong>
        </span>
      ))}
      <span>
        {' '}
        Due: <strong data-testid="header-due-total">{dueTotal}</strong>
      </span>
      <span>
        {' '}
        Overdue: <strong data-testid="header-overdue-total">{overdueTotal}</strong>
      </span>
    </header>
  );
}

export const contribution = SheetPanels.fill({ order: -100, Component: SheetHeader });

/** How many days back from the sheet's today a claim keeps its person active: dated within the 30
 *  days up to and including today (today and the 29 days before it). */
const ACTIVE_DAYS = 30;

/** The yyyy-mm-dd `days` days before `date`. */
function daysBefore(date: string, days: number): string {
  return new Date(Date.parse(`${date}T00:00:00Z`) - days * 86_400_000).toISOString().slice(0, 10);
}

/** Whether a person is active on the sheet's `today`: they have an OPEN or PENDING claim that counts
 *  (see `live`) dated within the 30 days up to and including today. `claims` may be the whole sheet's. */
export function isActive(person: Person, claims: Claim[], today: string): boolean {
  if (today === '') return false;
  const since = daysBefore(today, ACTIVE_DAYS - 1);
  return live(
    claims.filter((c) => c.personId === person.id),
    (_, date) => heldOn(person, date, today),
  ).some((c) => isOpen(c) && c.date >= since && c.date <= today);
}

